    ms_output.rate_t_s.z = 0.0;
    ms_output.rate_norm_t_s = 0.0;
    ms_output.field_energy_t2 = 0.0;
    return;
}

// 2. Handle Disable or Invalid Inputs
if (!ms_input.enable || 
    ms_input.field_body_t == NULL || 
    !adcs_is_finite_vec3(ms_input.field_body_t)) {

    if (!ms_input.enable) {
        // Disabled: Clear history, set EMPTY
        ms_state.mode = MS_EMPTY;
        ms_state.rejects = 0;
        ms_state.previous_field_t.x = 0.0;
        ms_state.previous_field_t.y = 0.0;
        ms_state.previous_field_t.z = 0.0;

        ms_output.mode = MS_EMPTY;
        ms_output.rejects = 0;
        ms_output.accepted_field_t.x = 0.0;
        ms_output.accepted_field_t.y = 0.0;
        ms_output.accepted_field_t.z = 0.0;
        ms_output.rate_t_s.x = 0.0;
        ms_output.rate_t_s.y = 0.0;
        ms_output.rate_t_s.z = 0.0;
        ms_output.rate_norm_t_s = 0.0;
        ms_output.field_energy_t2 = 0.0;
    } else {
        // Invalid input (NULL, Nonfinite) -> Latch FAULT
        // Do not update history
        ms_state.mode = MS_FAULT;

        ms_output.mode = MS_FAULT;
        ms_output.rejects = ms_state.rejects;
        ms_output.accepted_field_t = ms_state.previous_field_t;
        ms_output.rate_t_s = (adcs_vec3_t){0,0,0};
        ms_output.rate_norm_t_s = 0.0;
        ms_output.field_energy_t2 = 0.0;
    }
    return;
}

// 3. Valid Input Processing
double dt = ms_input.dt_s;
const adcs_vec3_t *current_field = ms_input.field_body_t;

// Calculate field energy for every valid sample
double field_energy_t2 = adcs_vec3_dot(current_field, current_field);

// Check for degenerate zero field -> Latch FAULT
if (field_energy_t2 <= FLT64_ZERO) {
     ms_state.mode = MS_FAULT;

     ms_output.mode = MS_FAULT;
     ms_output.rejects = ms_state.rejects;
     ms_output.accepted_field_t = ms_state.previous_field_t;
     ms_output.rate_t_s = (adcs_vec3_t){0,0,0};
     ms_output.rate_norm_t_s = 0.0;
     ms_output.field_energy_t2 = 0.0;
     return;
}

// Determine Mode Logic based on State
if (ms_state.mode == MS_EMPTY) {
    // First valid field initializes history
    ms_state.previous_field_t = *current_field;
    ms_state.rejects = 0;
    ms_state.mode = MS_TRACK;

    ms_output.mode = MS_TRACK;
    ms_output.rejects = 0;
    ms_output.accepted_field_t = ms_state.previous_field_t;
    ms_output.rate_t_s = (adcs_vec3_t){0, 0, 0};
    ms_output.rate_norm_t_s = 0.0;
    ms_output.field_energy_t2 = field_energy_t2;

} else {
    // Later samples (TRACK or REJECT state)
    adcs_vec3_t delta = adcs_vec3_sub(current_field, &ms_state.previous_field_t);
    adcs_vec3_t rate_t_s = adcs_vec3_scale(&delta, 1.0 / dt);
    double rate_norm_t_s = adcs_vec3_norm(&rate_t_s);

    ms_output.rate_t_s = rate_t_s;
    ms_output.rate_norm_t_s = rate_norm_t_s;
    ms_output.field_energy_t2 = field_energy_t2;

    if (rate_norm_t_s <= ms_config.max_slew_t_s) {
        // Accepted
        ms_state.previous_field_t = *current_field;
        ms_state.rejects = 0;
        ms_state.mode = MS_TRACK;

        ms_output.mode = MS_TRACK;
        ms_output.rejects = 0;
        ms_output.accepted_field_t = ms_state.previous_field_t;

    } else {
        // Rejected
        ms_state.rejects++;
        ms_output.rejects = ms_state.rejects;

        // Preserve field (no update to previous_field_t)
        ms_output.accepted_field_t = ms_state.previous_field_t;

        if (ms_state.rejects >= ms_config.max_rejects) {
            ms_state.mode = MS_FAULT;
            ms_output.mode = MS_FAULT;
        } else {
            ms_state.mode = MS_REJECT;
            ms_output.mode = MS_REJECT;
        }
    }
}

